package org.example.api.quotation;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.*;import org.example.config.ConfigManager;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
public final class QuotationApiClient{private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();private final ObjectMapper json=new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,false);private final String base;public QuotationApiClient(){String b=ConfigManager.getDataApiBaseUrl();while(b.endsWith("/"))b=b.substring(0,b.length()-1);base=b;}
 public List<QuoteDto> list(){return get("/api/quotations",new TypeReference<List<QuoteDto>>(){});}public List<LineDto> lines(int id){return get("/api/quotations/"+id+"/lines",new TypeReference<List<LineDto>>(){});}public QuoteDto save(SaveRequest d){return d.id()==null?post("/api/quotations",d,QuoteDto.class):put("/api/quotations/"+d.id(),d,QuoteDto.class);}public void notes(int id,String v){put("/api/quotations/"+id+"/notes",new Text(v),Ok.class);}public void markSent(int id,String channel){postNoBody("/api/quotations/"+id+"/sent?channel="+enc(channel));}public void followUp(int id,String date,String notes){post("/api/quotations/"+id+"/follow-up",new FollowUp(date,notes),Ok.class);}public String convert(int id,String user){return post("/api/quotations/"+id+"/convert?user="+enc(user),null,Text.class).value();}public String duplicate(int id,String user){return post("/api/quotations/"+id+"/duplicate?user="+enc(user),null,Text.class).value();}public void delete(int id){deleteReq("/api/quotations/"+id);}
 private <T>T get(String p,Class<T>c){return req("GET",p,null,c,null);}private <T>T get(String p,TypeReference<T>t){return req("GET",p,null,null,t);}private <T>T post(String p,Object b,Class<T>c){return req("POST",p,b,c,null);}private <T>T put(String p,Object b,Class<T>c){return req("PUT",p,b,c,null);}private void postNoBody(String p){req("POST",p,null,Ok.class,null);}private void deleteReq(String p){req("DELETE",p,null,Ok.class,null);}private <T>T req(String m,String p,Object body,Class<T>c,TypeReference<T>t){try{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(base+p)).timeout(Duration.ofSeconds(30)).header("Accept","application/json");if(body!=null)b.header("Content-Type","application/json").method(m,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else b.method(m,HttpRequest.BodyPublishers.noBody());var r=http.send(b.build(),HttpResponse.BodyHandlers.ofString());if(r.statusCode()<200||r.statusCode()>=300)throw new IllegalStateException("Quotation API error ("+r.statusCode()+"): "+r.body());return t!=null?json.readValue(r.body(),t):json.readValue(r.body(),c);}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}catch(IOException e){throw new IllegalStateException("Cannot reach quotation API at "+base,e);}}private String enc(String v){return URLEncoder.encode(v==null?"":v,StandardCharsets.UTF_8);}
 public record QuoteDto(int id,int customerId,String no,String date,String customer,String valid,String status,String followUp,String converted,String salesperson,String createdBy,double amount,String phone,String email,String gstin,String source,String remarks,double discount){}public record LineDto(String code,String description,double quantity,double rate,double gst,double discount,double total){}public record SaveRequest(Integer id,String date,String valid,int customerId,double subtotal,double discountAmount,double gstAmount,double total,String remarks,String followUp,String salesperson,String source,String createdBy,List<LineDto> lines){}public record FollowUp(String date,String notes){}public record Text(String value){}public record Ok(boolean success,String message){}
}
